以下是为丧尸末日场景设计的动态NPC生成系统，采用模块化结构，包含情境参数、生成算法和多样性保障机制：

```json
{
  "动态NPC生成引擎": {
    // 核心情境参数
    "情境参数": [
      {
        "维度": "地理环境",
        "参数": [
          {"name": "区域类型", "values": ["废弃都市", "军事基地", "森林哨站", "地下隧道", "海岸避难所"]},
          {"name": "污染等级", "values": ["低(1-3级)", "中(4-6级)", "高(7-9级)", "死区(10级)"]},
          {"name": "资源指数", "values": ["匮乏", "平衡", "富足"]}
        ]
      },
      {
        "维度": "时间因素",
        "参数": [
          {"name": "末日阶段", "values": ["爆发初期(0-6月)", "崩溃期(7-24月)", "废土纪元(25月+)" ]},
          {"name": "特殊事件", "values": ["尸潮来袭", "血月之夜", "酸雨季节", "疫苗谣言"]}
        ]
      },
      {
        "维度": "玩家状态",
        "参数": [
          {"name": "感染程度", "values": ["洁净", "潜伏期", "中期感染", "濒临变异"]},
          {"name": "阵营声望", "values": ["通缉犯", "中立者", "地区英雄", "传奇幸存者"]},
          {"name": "携带物资", "values": ["赤贫", "基础装备", "移动军火库"]}
        ]
      }
    ],

    // NPC生成算法
    "生成逻辑": {
      "步骤1_确定身份模板": {
        "公式": "ROLL d100 + 区域权重 + 事件修正",
        "模板库": [
          {"id": "survivor", "name": "幸存者", "权重": 30, "触发条件": "资源指数≠匮乏"},
          {"id": "scavenger", "name": "拾荒者", "权重": 25, "触发条件": "区域类型=废弃都市"},
          {"id": "cultist", "name": "邪教徒", "权重": 15, "触发条件": "污染等级≥中"},
          {"id": "mutant", "name": "变异人", "权重": 10, "触发条件": "污染等级≥高"},
          {"id": "deserter", "name": "叛逃士兵", "权重": 20, "触发条件": "军事基地/玩家声望<中立者"}
        ]
      },

      "步骤2_动态特性注入": {
        "性格矩阵": [
          ["偏执狂", "理想主义者", "实用主义者", "反社会者"],
          ["创伤后应激", "冷血算计", "病态乐观", "救世主情结"]
        ],
        "生成规则": "从矩阵中随机选择1-2个特质组合",

        "背景故事库": {
          "职业残留": ["前医生", "机械师", "教师", "罪犯", "程序员"],
          "执念对象": ["寻找女儿", "复仇", "保护圣经", "收集玩偶", "销毁研究数据"],
          "末日转折点": ["吃过人肉", "杀死感染者配偶", "被教派拯救", "发现免疫体质"]
        }
      },

      "步骤3_装备与能力生成": {
        "装备表": [
          {"类型": "近战武器", "选项": ["水管", "消防斧", "电击棒", "武士刀"], "稀有度": [40,30,20,10]},
          {"类型": "远程武器", "选项": ["手枪", "霰弹枪", "十字弩", "火焰喷射器"], "条件": "军事基地权重+20%"},
          {"类型": "特殊装备", "选项": ["防毒面具", "夜视仪", "自制雷达", "血清注射器"], "条件": "污染等级≥高"}
        ],

        "生存技能": [
          {"name": "陷阱专家", "效果": "提供安全路线", "触发": "森林/隧道区域"},
          {"name": "机械师", "效果": "修复载具", "触发": "携带废零件"},
          {"name": "病毒学者", "效果": "识别感染阶段", "触发": "中高污染区"}
        ]
      },

      "步骤4_关系网绑定": {
        "关系类型": ["盟友", "情报源", "潜在叛徒", "血仇目标", "救命恩人"],
        "生成算法": {
          "基础": "随机选择1种关系",
          "深度绑定": "当玩家声望>地区英雄时，25%概率生成[传奇关联]",
          "传奇关联": ["你父亲的战友", "病毒零号病人", "前保护伞科学家"]
        }
      }
    },

    // 防重复机制
    "多样性保障": [
      "记忆最近生成的5个NPC特征组合",
      "当新NPC相似度>70%时：强制激活[突变开关]",
      "突变开关选项": [
        "增加隐藏变异特征（如：第三只眼/光合作用皮肤）",
        "反转道德立场（圣徒变食人族）",
        "植入虚假记忆（其实是AI仿生人）"
      ]
    ],

    // AI交互指令
    "叙事指令集": [
      "首次描述NPC时必须包含：{外观特征+异常行为+环境互动}",
      "当玩家感染程度>潜伏期时：15%NPC携带抗体或抑制剂",
      "血月之夜：所有NPC的恐惧值+30%，背叛概率×2"
    ]
  }
}
```

### 🌟 NPC生成示例
**情境输入**：  
`{区域:军事基地, 污染:高, 事件:尸潮来袭, 玩家状态:中期感染}`  

**生成结果**：
```python
{
  "代号": "灰狐",
  "身份": "叛逃士兵(基因改造实验体)",
  "特征": ["左臂机械义肢", "瞳孔呈蛇类竖纹", "不停嚼抗辐射药片"],
  "背景": "前保护伞快速反应部队成员，在实验中获得增强体能但失去痛觉",
  "装备": ["电磁步枪(电量37%)", "钛合金护颈", "实验日志芯片"],
  "目标": "摧毁基地主服务器防止追踪",
  "交互选项": [
    "A. 合作突破尸潮（需分享抑制剂）",
    "B. 抢夺他的电磁步枪（触发死斗）",
    "C. 揭露其背叛行为（智力对抗）"
  ],
  "隐藏属性": {
    "变异进度": 68%,
    "忠诚度": -20, // 负值意味背叛倾向
    "秘密": "携带G病毒中和剂"
  }
}
```

### 🔄 动态适应系统
1. **环境反馈机制**  
   - 当玩家反复抢劫商人时，新生成NPC将出现：
     ```json
     {"特征":["设置饵雷","雇佣保镖"], "初始态度": "敌意"}
     ```

2. **进化关联**  
   - 若玩家激活「丧尸智慧进化」路线，将解锁特殊NPC：
     ```
     名称: "哀鸣向导"
     类型: 半感染先知
     能力: 通过丧尸脑波预测尸潮
     出现条件: 智慧丧尸击杀数>50
     ```

3. **跨区域联动**  
   - NPC可能携带其他区域信息：
     ```
     当生成拾荒者时，15%概率携带：
        {地图残片: "北境联盟补给路线", 有效期: "3个游戏日"}
     ```

### 💡 设计目的
1. **情境融合**：NPC属性实时响应环境变化（如酸雨季节生成防化服NPC）  
2. **玩家镜像**：高感染玩家遭遇更多变异人，强化角色代入感  
3. **叙事种子**：每个NPC携带独立支线任务链（如"收集玩偶"可延伸至儿童避难所惨案）  
4. **生态循环**：被抛弃的NPC可能转化为后续BOSS（如商人复仇者带领掠夺者团伙）

> 使NPC能基于历史交互做出合理反应，避免重复行为模式

