      {
        "类型": "环境压力",
        "参数": [
          {"name": "辐射暴露", "阈值": ">500rad", "进化方向": ["能量吸收", "放射性掌控"]},
          {"name": "病毒浓度", "阈值": "死区级(10级)", "进化方向": ["共生体适应", "病原体操控"]},
          {"name": "极端气候", "阈值": "持续3天", "进化方向": ["温度免疫", "环境同化"]}
        ]
